private boolean isPartialCoordinateInput(InputTextView input) {
    String inputText = input.getInputText();
    return inputText != null && inputText.length() == 1 && inputText.charAt(0) == '-';
}

/**
 * Gets the coordinates as entered in the latitude and longitude {@link InputTextView} objects.
 * The text views are always kept in sync with the map, but can also be edited manually by the
 * user; that's why the text views, and not the map, are the source of the fishing spot's
 * coordinates.
 *
 * @return A valid {@link LatLng} object, or null if the entered coordinates are invalid.
 */
@Nullable
private LatLng getInputCoordinates() {
    Double latitude = parseCoordinateInput(mLatitudeView);
    Double longitude = parseCoordinateInput(mLongitudeView);

    if (latitude == null || longitude == null)
        return null;

    LatLng coordinates = new LatLng(latitude, longitude);

    if (!isValidCoordinates(coordinates))
        return null;

    return coordinates;
}

/**
 * @return True if the given {@link LatLng} is within valid latitude and longitude bounds;
 *         false otherwise.
 */
private boolean isValidCoordinates(LatLng coordinates) {
    return (coordinates.latitude >= -90 && coordinates.latitude <= 90) &&
           (coordinates.longitude >= -180 && coordinates.longitude <= 180);
}

